      formulas: [{ eq: '½mv_i² + mgh_i (+ ½kx_i²) = ½mv_f² + mgh_f (+ ½kx_f²)', id: 'consme', vars: [['v', 'speed', 'm/s'], ['h', 'height', 'm'], ['x', 'spring deformation', 'm']], when: 'Only gravity and spring forces do work.' }],
